(()=>{
'use strict';
const config=window.ONESASH_CONFIG||{projects:[],technologies:[],socialLinks:[]};
const $=(selector,root=document)=>root.querySelector(selector), $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const media=matchMedia('(prefers-reduced-motion: reduce)');
const motionOK=()=>!media.matches&&typeof gsap!=='undefined';

// All user-facing content renders without animation libraries or JavaScript.
const header=$('#header'),menu=$('#menu-toggle'),navigation=$('#navigation');
function closeMenu(returnFocus=false){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');navigation.classList.remove('open');document.body.classList.remove('menu-open');if(returnFocus)menu.focus()}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';if(!open){closeMenu(true);return}menu.setAttribute('aria-expanded','true');menu.setAttribute('aria-label','Close menu');navigation.classList.add('open');document.body.classList.add('menu-open');if(motionOK())gsap.fromTo($$('a',navigation),{y:24,opacity:0},{y:0,opacity:1,stagger:.055,duration:.55,clearProps:'all',ease:'power3.out'});$('a',navigation).focus()});
$$('a',navigation).forEach(link=>link.addEventListener('click',()=>closeMenu()));
document.addEventListener('keydown',event=>{if(menu.getAttribute('aria-expanded')!=='true')return;if(event.key==='Escape'){closeMenu(true);return}if(event.key==='Tab'){const targets=[$('.brand',header),...$$('a',navigation),$('.nav-cta',header),menu];const current=targets.indexOf(document.activeElement);if(event.shiftKey&&current===0){event.preventDefault();menu.focus()}else if(!event.shiftKey&&current===targets.length-1){event.preventDefault();targets[0].focus()}}});
const mobileMenu=matchMedia('(max-width:850px)');mobileMenu.addEventListener('change',event=>{if(!event.matches)closeMenu()});
function onScroll(){header.classList.toggle('scrolled',scrollY>20)}window.addEventListener('scroll',onScroll,{passive:true});onScroll();
if('IntersectionObserver' in window){const navObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){$$('a',navigation).forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-20% 0px -60% 0px',threshold:0});$$('main section[id]').filter(s=>$('a[href="#'+s.id+'"]',navigation)).forEach(s=>navObserver.observe(s))}
// Smooth only explicit anchor navigation; focus and browser-driven scrolling stay immediate.
$$('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const target=document.querySelector(link.hash);if(!target)return;event.preventDefault();target.scrollIntoView({behavior:media.matches?'auto':'smooth',block:'start'});history.replaceState(null,'',link.hash);if(event.detail===0){target.tabIndex=-1;target.focus({preventScroll:true})}}));
// Details stay native and keyboard accessible; GSAP animates only their visible content.
function animateDetail(details,content){let closing=false;const summary=$('summary',details);summary.addEventListener('click',event=>{if(!motionOK())return;event.preventDefault();if(closing)return;if(details.open){closing=true;gsap.to(content,{height:0,opacity:0,duration:.3,ease:'power2.inOut',overwrite:true,onComplete(){details.open=false;closing=false;gsap.set(content,{clearProps:'height,opacity'});ScrollTrigger.refresh()}})}else{details.open=true;gsap.fromTo(content,{height:0,opacity:0},{height:'auto',opacity:1,duration:.45,ease:'power3.out',overwrite:true,onComplete(){gsap.set(content,{clearProps:'height,opacity'});ScrollTrigger.refresh()}})}})}
$$('.faq').forEach(faq=>animateDetail(faq,$('.faq-answer',faq)));
// Project and technology inventories are intentionally empty until verified data is supplied.
function safeURL(url){try{const parsed=new URL(url,location.origin);return ['http:','https:'].includes(parsed.protocol)?parsed.href:null}catch{return null}}
function addText(parent,tag,text,className=''){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;parent.append(el);return el}
if(config.projects?.length){$('#work-placeholder').hidden=true;config.projects.forEach(project=>{const article=document.createElement('article');article.className='project-card';if(project.image&&safeURL(project.image)){const img=document.createElement('img');img.src=safeURL(project.image);img.alt=project.imageAlt||project.title;img.loading='lazy';article.append(img)}const copy=document.createElement('div');addText(copy,'span',project.category||'','eyebrow');addText(copy,'h3',project.title);addText(copy,'p',project.overview||'');addText(copy,'p',(project.services||[]).join(' / '),'eyebrow');addText(copy,'p',(project.technologies||[]).join(' / '),'eyebrow');if(project.url&&safeURL(project.url)){const link=addText(copy,'a','View project ↗','plain-link');link.href=safeURL(project.url)}const mark=document.createElement('div');mark.className='project-monogram';mark.setAttribute('aria-hidden','true');mark.innerHTML='<span>'+String(config.projects.indexOf(project)+1).padStart(2,'0')+'</span><b>↗</b>';article.prepend(mark);article.append(copy);$('#projects').append(article)})}
if(config.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email)){const email=$('#contact-email');email.hidden=false;email.href='mailto:'+config.email;email.textContent=config.email;email.className='contact-email-link';const footerEmail=$('.footer-email')||addText($('#footer-contact'),'a',config.email);footerEmail.textContent=config.email;footerEmail.href=email.href}
if(config.phones?.length){$$('.company-phones').forEach(group=>{group.replaceChildren();config.phones.filter(phone=>/^tel:\+?\d+$/.test(phone.href)).forEach(phone=>{const link=addText(group,'a','');link.href=phone.href;addText(link,'span','CALL');link.append(document.createTextNode(phone.label));addText(link,'span','↗')})})}
(config.socialLinks||[]).forEach(social=>{if(safeURL(social.url)){const link=addText($('#social-links'),'a',social.label);link.href=safeURL(social.url)}});
const form=$('#contact-form'),status=$('#form-status'),submit=$('[type=submit]',form);
const fieldMessages={name:'Please enter your name (at least 2 characters).',email:'Please enter a valid email address.',project:'Please choose a project type.',message:'Please add a little more detail (at least 10 characters).'};
function validate(){let first=null;Object.entries(fieldMessages).forEach(([name,message])=>{const field=form.elements[name];let valid=field.checkValidity()&&field.value.trim().length>=(name==='message'?10:name==='name'?2:1);$('#error-'+name).textContent=valid?'':message;field.setAttribute('aria-invalid',String(!valid));if(!valid&&!first)first=field});if(first){first.focus();status.textContent='Please check the highlighted fields.'}return !first}
$$('input,select,textarea',form).forEach(field=>field.addEventListener('input',()=>{if(field.getAttribute('aria-invalid')==='true'&&field.checkValidity()&&field.value.trim().length>=(field.name==='message'?10:field.name==='name'?2:1)){field.removeAttribute('aria-invalid');const error=$('#error-'+field.name);if(error)error.textContent=''}}));
const endpoint=config.contactEndpoint&&safeURL(config.contactEndpoint);if(endpoint){$('#form-availability').textContent='Your details will be used to respond to this enquiry.'}else if(config.email){$('#form-availability').textContent='Opens an enquiry draft in your email app. Review and send it there, or email us directly.';submit.innerHTML='Prepare email enquiry <span>↗</span>'}
form.addEventListener('submit',async e=>{e.preventDefault();if(!validate())return;if(!endpoint){if(config.email){const values=Object.fromEntries(new FormData(form));const body=Object.entries(values).map(([key,value])=>key.toUpperCase()+': '+(value||'Not provided')).join('\n\n');const draft='mailto:'+config.email+'?subject='+encodeURIComponent('Project enquiry — '+values.name)+'&body='+encodeURIComponent(body);status.textContent='Your email draft is ready. Review and send it in your email app; it has not been sent by this website.';window.location.href=draft}else status.textContent='Your enquiry has not been sent. Please download your brief to keep a copy.';return}submit.disabled=true;submit.textContent='Sending…';status.textContent='Sending your enquiry…';try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form))),signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Submission failed');status.textContent='Thank you. Your enquiry has been sent.';form.reset()}catch(error){status.textContent='Your enquiry could not be sent. Please try again, or download your brief to keep a copy.'}finally{submit.disabled=false;submit.innerHTML='Send your enquiry <span>↗</span>'}});
$('#download-brief').addEventListener('click',()=>{const entries=Object.fromEntries(new FormData(form));const content='ONESASH — PROJECT ENQUIRY\n\n'+Object.entries(entries).map(([key,value])=>key.toUpperCase()+': '+(value||'Not provided')).join('\n\n');const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='OneSash-project-brief.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Your brief has been downloaded to your device. It has not been sent.'});
// Motion and new sections are initialized by refinement.js.
})();
